node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db', { readonly: true });

// Get cart
const cart = db.prepare('SELECT * FROM carts WHERE customer_id = ?').get('user_fbab7801');
console.log('=== Cart ===');
console.log(JSON.stringify(cart, null, 2));

// Get cart items
const items = db.prepare('SELECT * FROM cart_items WHERE customer_id = ?').all('user_fbab7801');
console.log('\n=== Cart Items ===');
console.log(JSON.stringify(items, null, 2));

// Get product details for each cart item
if (items.length > 0) {
  const productIds = items.map(i => i.product_id);
  const placeholders = productIds.map(() => '?').join(',');
  const products = db.prepare('SELECT product_id, name, category, brand, current_price, price FROM products WHERE product_id IN (' + placeholders + ')').all(...productIds);
  console.log('\n=== Product Details ===');
  console.log(JSON.stringify(products, null, 2));
}

db.close();
"
